   const createdAt = record.createdAt; // already a fixed value
   return <CreatedAt iso={createdAt.toISOString()} />;

   // Client Component
   'use client';
   export function CreatedAt({ iso }: { iso: string }) {
     return <time dateTime={iso}>{new Date(iso).toLocaleTimeString('en-US', { timeZone: 'UTC' })}</time>;
   }
